Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <algorithm>
#include <cstdlib>
#include <cstring>
#include <queue>

using namespace std;

struct Cell { int r,c,dis; };

const int dr[4] = {-1,0,1,0};
const int dc[4] = {0,-1,0,1};

queue<Cell> q;
char s[20];

int N, SUP, M, LIM, pathLen, aug, sink;
int src[12][12], dst[12][12], zd[12][12];
int cap[205][205], flow[205][205], path[205], lev[205], gap[203];
bool alive, found, walk[12][12], walkSave[12][12];

bool inside(int r, int c)
{
    return r >= 0 && r < M && c >= 0 && c < M;
}

void dfsAug(int x, int limit)
{
    if (x == sink)
    {
        aug = limit;
        found = true;
        return;
    }
    int best = N + 2;
    for (int y = 0; y <= N + 1; ++y)
    {
        if (flow[x][y] < cap[x][y])
        {
            best = min(best, lev[y]);
            if (lev[x] == lev[y] + 1)
            {
                path[++pathLen] = y;
                dfsAug(y, min(limit, cap[x][y] - flow[x][y]));
                if ((!alive) || found)
                    return;
                path[pathLen--] = 0;
            }
        }
        if (flow[y][x] > 0)
        {
            best = min(best, lev[y]);
            if (lev[x] == lev[y] + 1)
            {
                path[++pathLen] = -y;
                dfsAug(y, min(limit, flow[y][x]));
                if ((!alive) || found)
                    return;
                path[pathLen--] = 0;
            }
        }
    }
    if (best + 1 != lev[x])
    {
        --gap[lev[x]];
        if (gap[lev[x]] == 0)
            alive = false;
        lev[x] = best + 1;
        ++gap[lev[x]];
    }
}

bool augmentingPath()
{
    found = false;
    aug = SUP;
    pathLen = 0;
    path[0] = 0;
    dfsAug(0, SUP);
    return found;
}

void updateFlow()
{
    for (int x = 1; x <= pathLen; ++x)
    {
        if (path[x] > 0)
            flow[abs(path[x-1])][path[x]] += aug;
        else
            flow[-path[x]][abs(path[x-1])] -= aug;
    }
}

int main()
{
    scanf("%d %d", &M, &LIM);
    memset(cap, 0, sizeof(cap));
    memset(flow, 0, sizeof(flow));
    memset(src, 0, sizeof(src));
    memset(dst, 0, sizeof(dst));
    memset(walk, 0, sizeof(walk));
    memset(zd, 0, sizeof(zd));
    memset(lev, 0, sizeof(lev));
    memset(gap, 0, sizeof(gap));

    for (int i = 0; i < M; ++i)
    {
        scanf("%s", s);
        for (int j = 0; j < M; ++j)
        {
            if (s[j] == 'Z')
            {
                Cell c;
                c.r = i;
                c.c = j;
                c.dis = 0;
                q.push(c);
            }
            else if (s[j] != 'Y')
            {
                walk[i][j] = true;
                zd[i][j] = LIM;
                int k = s[j] - '0';
                if (k > 0)
                {
                    src[i][j] = ++N;
                    cap[0][N] = k;
                    SUP += k;
                }
            }
        }
    }
    memcpy(walkSave, walk, sizeof(walk));

    for (int i = 0; i < M; ++i)
    {
        scanf("%s", s);
        for (int j = 0; j < M; ++j)
        {
            if (s[j] == 'Z' || s[j] == 'Y')
                continue;
            int k = s[j] - '0';
            if (k > 0)
            {
                dst[i][j] = ++N;
                cap[N][M * M + 1] = k;
            }
        }
    }

    sink = N + 1;
    if (N != M * M)
    {
        for (int i = 0; i < M; ++i)
            for (int j = 0; j < M; ++j)
                if (dst[i][j] > 0)
                {
                    int v = dst[i][j];
                    cap[v][sink] = cap[v][M * M + 1];
                    cap[v][M * M + 1] = 0;
                }
    }

    while (!q.empty())
    {
        Cell cur = q.front();
        q.pop();
        int i = cur.r, j = cur.c;
        zd[i][j] = cur.dis;
        for (int d = 0; d < 4; ++d)
        {
            int ni = i + dr[d], nj = j + dc[d];
            if (inside(ni, nj) && walk[ni][nj])
            {
                walk[ni][nj] = false;
                Cell nxt;
                nxt.r = ni;
                nxt.c = nj;
                nxt.dis = cur.dis + 1;
                q.push(nxt);
            }
        }
    }

    for (int i = 0; i < M; ++i)
    {
        for (int j = 0; j < M; ++j)
        {
            if (src[i][j] == 0)
                continue;
            memcpy(walk, walkSave, sizeof(walkSave));
            walk[i][j] = false;
            Cell st;
            st.r = i;
            st.c = j;
            st.dis = 0;
            q.push(st);
            while (!q.empty())
            {
                Cell cur = q.front();
                q.pop();
                int x = cur.r, y = cur.c;
                if (dst[x][y] > 0 && cur.dis <= zd[x][y])
                    cap[src[i][j]][dst[x][y]] = SUP;
                if (cur.dis + 1 > LIM || cur.dis >= zd[x][y])
                    continue;
                for (int d = 0; d < 4; ++d)
                {
                    int nx = x + dr[d], ny = y + dc[d];
                    if (inside(nx, ny) && walk[nx][ny])
                    {
                        walk[nx][ny] = false;
                        Cell nxt;
                        nxt.r = nx;
                        nxt.c = ny;
                        nxt.dis = cur.dis + 1;
                        q.push(nxt);
                    }
                }
            }
        }
    }

    gap[0] = N + 2;
    alive = true;
    while (alive && lev[0] <= N + 2)
        while (augmentingPath())
            updateFlow();

    int ans = 0;
    for (int i = 1; i <= N; ++i)
        ans += flow[i][sink];
    printf("%d\n", ans);
    return 0;
}
